import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Text content bridging
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMap = {};
  for (const item of items) {
    textMap[item.text] = item;
  }

  // Design tokens
  const cardW = 1.5;
  const cardH = 1.9;
  const cardGap = 0.25;
  const cardCount = 3;
  const rowW = cardW * cardCount + cardGap * (cardCount - 1);
  const rowStartX = -rowW / 2;

  const cornerRadius = 0.06;
  const hairlineBorder = 0.006;
  const padding = 0.375;
  const iconDiameter = 0.4;
  const iconExtrude = 0.05;
  const iconGap = 0.25;
  const titleGap = 0.125;

  const colors = config.intent?.visualSpec?.colors || {};
  const bgColor = colors.background || '#0b0b10';
  const surfaceColor = colors.surface || '#16161d';
  const accentColor = colors.accent || '#ff2a38';
  const paperColor = colors.paper || '#e8ecf2';

  // Gradient backdrop (stage)
  const backdropW = 7;
  const backdropH = 6;
  const backdropGeom = new THREE.PlaneGeometry(backdropW, backdropH);

  const gradStops = colors.gradientStops || [
    { at: 0, hex: '#191921' },
    { at: 1, hex: '#121218' }
  ];
  const color0 = new THREE.Color(gradStops[0].hex);
  const color1 = new THREE.Color(gradStops[1].hex);

  const backdropMat = new MeshStandardNodeMaterial({
    colorNode: mix(
      vec3(color0.r, color0.g, color0.b),
      vec3(color1.r, color1.g, color1.b),
      smoothstep(0, 1, uv().y)
    ),
    metalness: 0,
    roughness: 1,
    emissive: new THREE.Color(0x000000),
  });

  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.receiveShadow = true;
  group.add(backdrop);

  // Card data
  const cardData = [
    { num: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { num: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { num: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' }
  ];

  const cards = [];
  const timelines = [];

  cardData.forEach((data, idx) => {
    const cardX = rowStartX + idx * (cardW + cardGap) + cardW / 2;

    // Card container group
    const cardGroup = new THREE.Group();
    cardGroup.position.set(cardX, 0, 0);
    cards.push(cardGroup);
    group.add(cardGroup);

    // Card background plane with gradient ramp
    const cardGeom = new THREE.PlaneGeometry(cardW, cardH);

    const cardGradColor0 = new THREE.Color(gradStops[0].hex);
    const cardGradColor1 = new THREE.Color(gradStops[1].hex);

    const cardMat = new MeshStandardNodeMaterial({
      colorNode: mix(
        vec3(cardGradColor0.r, cardGradColor0.g, cardGradColor0.b),
        vec3(cardGradColor1.r, cardGradColor1.g, cardGradColor1.b),
        smoothstep(0, 1, uv().y)
      ),
      metalness: uniform(0.25),
      roughness: uniform(0.6),
      clearcoat: uniform(0.15),
      emissive: new THREE.Color(0x000000),
    });

    const cardMesh = new THREE.Mesh(cardGeom, cardMat);
    cardMesh.position.z = 0;
    cardGroup.add(cardMesh);

    // Border (hairline stroke effect via wireframe substitute)
    const cardBorderGeom = new THREE.PlaneGeometry(cardW - hairlineBorder * 2, cardH - hairlineBorder * 2);
    const cardBorderMat = new THREE.MeshBasicNodeMaterial({
      color: 0x26262f,
      wireframe: false,
      emissive: 0x26262f,
    });
    const cardBorder = new THREE.LineSegments(
      new THREE.EdgesGeometry(cardGeom, 10),
      new THREE.LineBasicMaterial({ color: 0x26262f, linewidth: 1 })
    );
    cardBorder.position.z = 0.01;
    cardGroup.add(cardBorder);

    // Icon seat (machined disc)
    const iconSeatGeom = new THREE.CylinderGeometry(iconDiameter / 2, iconDiameter / 2, iconExtrude, 32);
    const iconSeatMat = new MeshStandardNodeMaterial({
      color: 0x1a1a20,
      metalness: uniform(0.5),
      roughness: uniform(0.55),
      clearcoat: uniform(0.2),
      emissive: new THREE.Color(0x000000),
    });
    const iconSeat = new THREE.Mesh(iconSeatGeom, iconSeatMat);

    // Position icon seat at top of card, vertically centered
    const iconY = cardH / 2 - padding - iconDiameter / 2;
    iconSeat.position.set(0, iconY, 0.05);
    iconSeat.rotation.x = Math.PI / 2;
    iconSeat.castShadow = true;
    cardGroup.add(iconSeat);

    // Icon glyph (emissive mono text)
    const iconText = ctx.fontAtlas.createText(data.num, {
      fontSize: 20,
      color: accentColor,
      align: 'center',
    });
    // Set emissive on icon text material
    if (iconText.children[0]?.material) {
      iconText.children[0].material.emissive = new THREE.Color(accentColor);
      iconText.children[0].material.emissiveIntensity = 1.6;
    }
    iconText.position.set(0, iconY, 0.08);
    iconText.scale.multiplyScalar(0.08);
    cardGroup.add(iconText);

    // Title text
    const titleY = iconY - iconDiameter / 2 - iconGap;
    const titleText = ctx.fontAtlas.createText(data.title, {
      fontSize: 20,
      color: paperColor,
      align: 'center',
      maxWidthPx: (cardW - padding * 2) * 50,
    });
    titleText.position.set(0, titleY, 0.02);
    titleText.scale.multiplyScalar(0.08);
    cardGroup.add(titleText);

    // Body text
    const bodyY = titleY - titleGap - 0.1;
    const bodyText = ctx.fontAtlas.createText(data.body, {
      fontSize: 13,
      color: paperColor,
      align: 'center',
      maxWidthPx: (cardW - padding * 2) * 50,
    });
    bodyText.position.set(0, bodyY, 0.02);
    bodyText.scale.multiplyScalar(0.08);
    cardGroup.add(bodyText);

    // Initial state for animation
    cardGroup.position.y = 0.2;
    cardGroup.material = cardMat;

    // Store icon text for hover glow
    cardGroup.userData.iconText = iconText;
    cardGroup.userData.iconSeat = iconSeat;
    cardGroup.userData.cardMesh = cardMesh;
    cardGroup.userData.contactShadow = null;
  });

  // Contact shadow planes under each card
  cards.forEach((card, idx) => {
    const shadowGeom = new THREE.PlaneGeometry(1.5, 0.3);
    const shadowMat = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.5,
      depthWrite: false,
    });
    const shadow = new THREE.Mesh(shadowGeom, shadowMat);
    shadow.position.set(0, -cardH / 2 - 0.15, -0.02);
    shadow.receiveShadow = true;
    card.add(shadow);
    card.userData.contactShadow = shadow;
  });

  // Stagger animation on load
  cards.forEach((card, idx) => {
    const tl = gsap.timeline();
    tl.fromTo(
      card.position,
      { y: 0.2, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      },
      idx * 0.08
    );
    timelines.push(tl);
  });

  // Hover handler
  group.userData.handlers = {
    hover: function(e) {
      if (!e.target || !e.target.parent) return;
      const card = e.target.parent;
      if (!cards.includes(card)) return;

      const isEnter = e.type === 'mouseenter';

      gsap.to(card.position, {
        y: isEnter ? 0.06 : 0,
        z: isEnter ? 0.12 : 0,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      });

      if (card.userData.contactShadow) {
        gsap.to(card.userData.contactShadow.scale, {
          x: isEnter ? 1.3 : 1,
          y: isEnter ? 1.2 : 1,
          duration: 0.18,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        });
        gsap.to(card.userData.contactShadow.material, {
          opacity: isEnter ? 0.7 : 0.5,
          duration: 0.18,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        });
      }

      if (card.userData.iconText && card.userData.iconText.children[0]?.material) {
        gsap.to(card.userData.iconText.children[0].material, {
          emissiveIntensity: isEnter ? 2.2 : 1.6,
          duration: 0.18,
          ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
        });
      }
    }
  };

  // Cleanup
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());
    cardMat.dispose();
    backdropMat.dispose();
    cards.forEach(card => {
      card.children.forEach(child => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      });
    });
    backdropGeom.dispose();
  };

  return group;
}
